'use strict';
// Detail screens retain their DOM so back navigation also retains unfinished edits.
const detailScreens=new Map();let detailSequence=0;const oldBindExperience=bind;
view=function(){return location.hash.slice(1)||'home'};
function navigate(route){history.pushState(null,'','#'+route);render();window.scrollTo(0,0)}
open=function(html){const parent=view(),id='detail/'+(++detailSequence),node=document.createElement('div');document.querySelector('#dialog-content')?.removeAttribute('id');node.id='dialog-content';node.className='detail-content';node.innerHTML=html;detailScreens.set(id,{node,parent});history.pushState(null,'','#'+id);render();window.scrollTo(0,0)};
close=function(){const page=detailScreens.get(view());navigate(page?.parent||'home')};
function backButton(route){return `<button class="back-link" data-go="${esc(route)}">← Back</button>`}
function dropZone(){return `<div class="document-drop"><label for="quick-document"><span class="drop-symbol" aria-hidden="true">↥</span><strong>Drop your paperwork here</strong><span>Shares, options, grants, flights. Ron will work out what it’s for and process it.</span><span class="browse-file">Choose a file ↗</span><input class="hidden-file" id="quick-document" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.csv,.doc,.docx,.xls,.xlsx"></label><p>Or forward to <button class="text-link" id="inbox-info">ron@ron.com</button></p><small>Demo: saves file details only. Analysis and the email inbox aren’t connected.</small></div>`}
const oldHomeExperience=home;
home=function(){ensurePlanner();return `<section class="wealth-intro"><span class="eyebrow">Your wealth</span><div class="wealth-number">${money(wealth())}<span class="money-dot" aria-hidden="true">●</span></div><button class="text-link" data-command="basis">How it’s counted →</button></section><section class="invest-overview"><h2>Available to invest</h2><div class="available-figure">${money(spare())}<span>available cash</span></div><div class="money-pills"><button data-go="money"><i>£</i> ${money(cashTotal())} total cash ↗</button><button data-go="money"><i>↗</i> ${money(liquidInvestments())} investments to sell ↗</button><button data-go="tax"><i>◒</i> ${money(recAmount())} ISA space ↗</button></div><p class="investment-nudge"><span aria-hidden="true">↗</span> You have ${money(recAmount())} of ISA space and enough personal cash to use it.</p><small class="muted">Illustrative suggestion. Your Partner checks eligibility and the investment first.</small><button class="primary make-investment" data-invest>Make investment <span>→</span></button></section><section class="planner-timeline"><div class="section-heading"><h2>Your timeline</h2><button class="text-link" id="add-event">Add event +</button></div>${timeline()}</section><section class="simple-upcoming income-list"><h2><span class="section-symbol">↓</span> Coming to you</h2>${upcomingList('income')}</section><section class="simple-upcoming tax-list"><h2><span class="section-symbol">↑</span> Tax to pay</h2>${upcomingList('tax')}</section><section class="simple-upcoming trade-list"><h2><span class="section-symbol">⇄</span> Planned transactions</h2>${upcomingList('trade')}</section><section class="home-paperwork">${dropZone()}</section><section class="home-tasks"><div class="section-heading"><h2>For you to review</h2><a href="#review">See all →</a></div>${reviewRows()}</section><section class="travel-teaser"><div class="section-heading"><h2>Travel</h2><button class="text-link" id="travel-plan">Add trip +</button></div><p><strong>132 UK nights</strong> recorded · illustrative 2026/27</p><p class="muted">${extraUKNights('Recorded')} additional recorded / ${extraUKNights('Planned')} planned UK calendar nights awaiting reconciliation. Residence tests and your planned move need a professional review.</p><button class="text-link" data-event="review">Move & inheritance planning →</button></section>`};
function reviewRows(){return `<button class="task-row" data-filing="accounts"><div><strong>Company accounts</strong><span>Draft example · 2 records still needed</span></div><span>→</span></button><button class="task-row" data-filing="personal"><div><strong>Your tax return</strong><span>£18,200 draft estimate · due 31 January</span></div><span>→</span></button>${outstanding().map(([a,b,c])=>`<button class="task-row" data-command="${c}"><div><strong>${a}</strong><span>${b}</span></div><span>→</span></button>`).join('')}`}
function filesPage(){return `<div class="page-heading"><h1>Files</h1><p>Documents, grants and agreements.</p></div>${dropZone()}<section><h2>Your documents <span class="count">${state.docs.length}</span></h2>${state.docs.length?state.docs.map(d=>`<button class="task-row" data-document="${esc(d.id)}"><div><strong>${esc(d.name)}</strong><span>${esc(d.kind)} · waiting for review</span></div><span>→</span></button>`).join(''):'<p class="muted">Nothing added yet. Start with a share confirmation, grant or agreement.</p>'}</section><section><h2>Prepared drafts</h2><button class="task-row" data-filing="accounts"><div><strong>2LR Investments Ltd · annual accounts</strong><span>Full branded example · 31 March 2026</span></div><span>→</span></button><button class="task-row" data-filing="personal"><div><strong>Personal tax return</strong><span>Full example · 2025/26</span></div><span>→</span></button></section>`}
function reviewPage(){return `<div class="page-heading"><h1>For review</h1><p>Read the summary. Open the draft. Approve when it’s ready.</p></div><section>${reviewRows()}</section><section><h2>Investment plans <span class="count">${state.requests.length}</span></h2>${state.requests.map(r=>`<button class="task-row" data-request="${r.id}"><div><strong>${money(r.amount)} · ${esc(r.name)}</strong><span>${esc(r.status)} · saved locally</span></div><span>→</span></button>`).join('')||'<p class="muted">No plans waiting for your Partner.</p>'}</section><p class="fine">Example accounts and tax packs need professional completion before approval. Nothing is submitted by this demo.</p>`}
render=function(){ensurePlanner();const v=view();document.querySelectorAll('header nav a').forEach(a=>{a.toggleAttribute('aria-current',a.hash==='#'+v);if(a.hasAttribute('aria-current'))a.setAttribute('aria-current','page')});const screen=$('#screen');screen.classList.toggle('is-detail',v.startsWith('detail/'));screen.classList.toggle('is-investment',v.startsWith('invest/'));if(v.startsWith('invest/')&&!plan.type&&v!=='invest/type'){history.replaceState(null,'','#invest/type');return render()}if(v.startsWith('detail/')&&detailScreens.has(v)){const page=detailScreens.get(v);screen.innerHTML=backButton(page.parent);document.querySelector('#dialog-content')?.removeAttribute('id');page.node.id='dialog-content';screen.append(page.node)}else if(v.startsWith('invest/')){screen.innerHTML=wizardPage(v.split('/')[1])}else if(window.ronScreens?.[v])screen.innerHTML=window.ronScreens[v]();else screen.innerHTML=v==='money'?moneyPage():v==='tax'?taxPage():v==='files'?filesPage():v==='review'?reviewPage():home();bind();};
bind=function(){oldBindExperience();document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));const zone=$('.document-drop label');if(zone){zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragging')};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=e=>{e.preventDefault();quickIntake(e.dataTransfer.files[0])}}document.querySelectorAll('[data-document]').forEach(b=>b.onclick=()=>{const d=state.docs.find(x=>x.id===b.dataset.document);open(`<h1>${esc(d.name)}</h1><dl class="review-list"><dt>Suggested category</dt><dd>${esc(d.kind)}</dd><dt>Status</dt><dd>Awaiting Partner review</dd><dt>Owner</dt><dd>${esc(d.owner)}</dd><dt>File size</dt><dd>${(d.size/1024).toFixed(1)} KB</dd></dl><p class="fine">Filename-based suggestion only. This prototype hasn’t stored the file contents, analysed them or changed your holdings.</p>`)});document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>{const r=state.requests.find(x=>x.id===b.dataset.request);open(`<h1>${esc(r.name)}</h1><p class="available-figure">${money(r.amount)}</p><p>${esc(r.status)}</p>${r.scenario?scenarioMarkup(r.scenario,r):'<p>Your Partner will review the investment and funding.</p>'}<p class="fine">Locally saved example. No money reserved, trade placed or request sent.</p>`)});bindWizard();};
// Only the modelling inputs below are assumed. No live recommendation engine is connected.
let plan={};try{plan=JSON.parse(sessionStorage.getItem(('ron-investment-draft-'+(window.RON_REGION||'uk'))))||{}}catch{}
invest=function(){plan={type:'',eis:'unknown',name:'',amount:12000,goal:'grow',years:'5',disposal:'',cross:true,sales:true,route:'auto',growth:20};navigate('invest/type')};
function steps(){return ['type',plan.type==='startup'?'eis':'goal','amount','horizon','funding','review']}
function choice(value,label,copy,selected=false){return `<button class="flow-choice ${selected?'selected':''}" data-choice="${value}"><span><strong>${label}</strong>${copy?'<small>'+copy+'</small>':''}</span><span aria-hidden="true">${selected?'✓':'→'}</span></button>`}
function flowShell(step,title,copy,body){const sequence=steps(),i=sequence.indexOf(step);return `${backButton(i>0?'invest/'+sequence[i-1]:'home')}<div class="flow-progress" aria-label="Step ${i+1} of ${sequence.length}">${sequence.map((x,j)=>'<i class="'+(j<=i?'done':'')+'"></i>').join('')}</div><p class="eyebrow">New investment · ${i+1} / ${sequence.length}</p><h1>${title}</h1><p class="flow-copy">${copy}</p><div class="flow-body">${body}</div><p class="fine">Planning demo. Your Partner approves the advice before you act.</p>`}
function wizardPage(step){if(!plan.type&&step!=='type')step='type';if(step==='type')return flowShell(step,'What are you investing in?','Start with the investment. We’ll work out the route.',choice('startup','A startup','New shares in a private company',plan.type==='startup')+choice('fund','A fund','Build or add to your portfolio',plan.type==='fund')+choice('other','Something else','Shares, property, gold or another asset',plan.type==='other')+choice('help','Help me choose','Start with what you want the money to do',plan.type==='help'));
if(step==='eis')return flowShell(step,'Does it qualify for EIS?','Some startup investments qualify for personal tax relief. Check the documents, or let your Partner check.',choice('yes','The company says it qualifies','Eligibility and your claim still need checking',plan.eis==='yes')+choice('unknown','I’m not sure','Upload the paperwork later',plan.eis==='unknown')+choice('no','No','Compare the other routes',plan.eis==='no'));
if(step==='goal')return flowShell(step,'What should this money do?','The tax treatment matters. So does having the right investment.',choice('grow','Grow','Reinvest. Give it time.',plan.goal==='grow')+choice('balance','Balance','Growth with some income.',plan.goal==='balance')+choice('return','Pay me an income','A regular return comes first.',plan.goal==='return'));
if(step==='amount')return flowShell(step,'How much are you putting in?','We’ll check the money available and keep your spending and tax reserves aside.',`<form id="flow-amount"><label for="flow-sum">Investment amount</label><div class="currency-input"><span>£</span><input id="flow-sum" type="number" min="1" max="3000000" step="1" required value="${plan.amount}"></div>${plan.type==='startup'||plan.type==='other'?`<label for="flow-name">${plan.type==='startup'?'Company name':'What is it?'}</label><input id="flow-name" required value="${esc(plan.name)}" placeholder="${plan.type==='startup'?'The company you want to back':'e.g. shares in…'}">`:''}<p class="muted">${money(spare())} cash available across your personal and company accounts.</p><button class="primary wide">Continue →</button></form>`);
if(step==='horizon')return flowShell(step,'When will you need it back?','We use this to flag holding requirements and plan future disposals.',choice('1','Within a year','Keep access to the money in mind.',plan.years==='1')+choice('5','Around five years','Some room for long-term planning.',plan.years==='5')+choice('10','Ten years or more','Focus on long-term growth.',plan.years==='10')+`<form id="flow-date"><label for="flow-disposal">Or set a planned disposal date</label><input type="date" min="2026-10-18" id="flow-disposal" value="${plan.disposal}"><button class="secondary wide">Use this date →</button></form>`);
if(step==='funding'){const candidates=compareRoutes(plan),s=chooseScenario(candidates,plan);return flowShell(step,'Your funding','Cash first. Then the cost of selling investments. Personal and company money stay distinct.',`<div class="source-toggles"><label><input id="flow-cross" type="checkbox" ${plan.cross?'checked':''}> Include shareholder loans between you and the company</label><label><input id="flow-sales" type="checkbox" ${plan.sales?'checked':''}> Include selling existing investments</label></div><div class="route-options">${candidates.map(c=>`<button data-route="${c.route}" class="route-choice ${s.route===c.route?'selected':''}"><span><strong>${c.route==='personal'?'Hold personally':'Hold in your company'}</strong><small>${c.shortfall?'Needs '+money(c.shortfall)+' more funding':money(c.now+c.future)+' modelled tax'}${c.route===s.route?' · selected':''}</small></span><span>${c.route===s.route?'✓':'→'}</span></button>`).join('')}</div>${scenarioMarkup(s,plan)}<p class="error" role="alert">${s.shortfall?'There isn’t enough permitted funding. Change the amount or sources.':''}</p><button class="primary wide" id="flow-to-review" ${s.shortfall?'disabled':''}>Review this plan →</button>`)}
const s=chooseScenario(compareRoutes(plan),plan);return flowShell('review','Review your investment','Your Partner checks the investment, funding and tax position.',`<div class="plan-summary"><span>${esc(plan.name||({fund:'Fund portfolio',help:'Investment shortlist'}[plan.type]||'New investment'))}</span><strong>${money(plan.amount)}</strong><p>${plan.years} year horizon${plan.disposal?' · planned sale '+when(plan.disposal):''}</p></div>${scenarioMarkup(s,plan)}${plan.type==='fund'||plan.type==='help'?`<div class="intelligent-note"><h3>${plan.goal==='return'?'An income fund shortlist':plan.goal==='balance'?'A balanced fund shortlist':'A diversified growth fund shortlist'}</h3><p>${s.isa?'Use the ISA space first for an eligible fund. ':''}Your Partner will choose suitable funds, risk level and costs. ${s.route==='company'?'Fund distributions need classification: interest and some fund returns are taxable; qualifying corporate dividends may be exempt.':'Accumulation funds outside an ISA can still produce taxable income.'}</p><small>No live fund recommendation has been generated.</small></div>`:''}<button class="primary wide" id="flow-save">Save for Partner review →</button><p class="fine">Saves this sample locally. No advice is released, cash reserved or trade placed.</p>`)
}
function personalSaleTax(gain){return Math.max(0,gain-Math.max(0,3000-ledger.allowances.cgt))*.24}
function compareRoutes(p){return ['personal','company'].map(route=>{let remaining=Number(p.amount),parts=[],now=0;const take=(label,limit,note)=>{const n=Math.min(remaining,Math.max(0,limit));if(n>0){parts.push({label,net:n,gross:n,tax:0,note});remaining-=n}};take(route==='personal'?'Personal cash':'Company cash',available(route==='personal'?'cash':'ficcash'),'Cash already marked available');if(p.cross)take(route==='personal'?'Company → you · loan repayment':'You → company · new shareholder loan',route==='personal'?Math.min(available('ficcash'),ledger.loans.filter(l=>l.borrower==='fic').reduce((a,l)=>a+l.balance,0)):available('cash'),route==='personal'?'Principal only; subject to balance and liquidity checks':'Recorded as new principal. No tax deduction.');if(p.sales&&remaining>0){const asset=ledger.positions.find(x=>x.id===(route==='personal'?'gia':'global')),price=value(asset),fraction=Math.max(0,(price-asset.cost)/price),tax=gross=>route==='personal'?personalSaleTax(gross*fraction):gross*fraction*.25;let lo=0,hi=price;for(let i=0;i<60;i++){const mid=(lo+hi)/2;if(mid-tax(mid)<remaining)lo=mid;else hi=mid}const gross=Math.min(price,hi),t=tax(gross),net=Math.min(remaining,gross-t);if(net>0){parts.push({label:'Sell '+asset.name,net,gross,tax:t,note:route==='personal'?'24% CGT assumption, after recorded remaining exemption':'25% company tax assumption on the gain'});now+=t;remaining-=net}}
const isa=route==='personal'&&(p.type==='fund'||p.type==='help')?Math.min(p.amount,recAmount()):0,gain=p.amount*.20,future=route==='company'?gain*.25:Math.max(0,(p.amount-isa)*.20)*.24,eis=route==='personal'&&p.type==='startup'&&p.eis==='yes'?Math.min(p.amount,Math.max(0,1000000-ledger.allowances.eis))*.30:0;return{route,parts,now,future,isa,eis,shortfall:Math.max(0,remaining)}})}
function chooseScenario(c,p){if(p.route!=='auto')return c.find(x=>x.route===p.route)||c[0];const eligible=c.filter(x=>x.shortfall<.01);if(p.type==='startup'&&p.eis==='yes'&&eligible.some(x=>x.route==='personal'))return eligible.find(x=>x.route==='personal');return eligible.sort((a,b)=>(a.now+a.future)-(b.now+b.future))[0]||c.sort((a,b)=>a.shortfall-b.shortfall)[0]}
function scenarioMarkup(s,p){return `<div class="funding-breakdown"><h3>${s.route==='personal'?'Personal ownership':'Company ownership'} <span class="status-pill">Illustrative route</span></h3><p class="route-reason">${p.type==='startup'&&p.eis==='yes'&&s.route==='personal'?'Personal ownership keeps a possible EIS claim open. A company subscription does not give you personal EIS relief.':s.isa?'Use your recorded ISA space first. Keep the rest outside the wrapper.':'Compare the ownership routes before committing the money.'}</p>${s.parts.map(x=>`<div class="funding-row"><div><strong>${esc(x.label)}</strong><small>${esc(x.note)}</small></div><strong class="positive">${money(x.net)}</strong></div>`).join('')}${s.parts.some(x=>x.tax)?`<p class="fine">Sale proceeds of ${money(s.parts.filter(x=>x.tax).reduce((a,x)=>a+x.gross,0))} include a ${money(s.now)} tax reserve; the funding amounts above are after that reserve.</p>`:''}${s.isa?`<div class="intelligent-note">${money(s.isa)} into an eligible stocks & shares ISA. ${p.amount>s.isa?money(p.amount-s.isa)+' held outside the ISA.':''} Eligibility and fund choice need confirmation.</div>`:''}<div class="tax-comparison"><div><span>Tax from selling now</span><strong class="tax-number">${money(s.now)}</strong><small>Due later; reserve at sale</small></div><div><span>Tax on a future 20% gain</span><strong class="tax-number">${money(s.future)}</strong><small>${s.eis?'Before possible EIS disposal relief':'Scenario, not a forecast'}</small></div></div>${s.eis?`<div class="intelligent-note"><strong>Potential EIS relief: up to ${money(s.eis)}</strong><p>Personal subscription only. Your Income Tax liability and eligibility aren’t verified, so this isn’t deducted from the costs. A minimum three-year holding condition applies; other conditions continue.</p></div>`:''}${p.type==='startup'&&(p.years==='1'||(p.disposal&&p.disposal<'2029-10-17'))?'<p class="warning-note">A short holding period may lose EIS relief. Startup shares can also be difficult to sell.</p>':''}<details class="model-assumptions"><summary>How this was compared</summary><p>Two ownership routes, using cash marked available, then an eligible shareholder loan, then a partial sale of the recorded personal equity fund or company equity fund. Reserved cash and ISA holdings aren’t sold. Loans and all disposals need professional approval.</p><p>Sample personal CGT rate: 24%; remaining recorded annual exemption applies to the immediate sale. Sample company rate: 25% on gains, with no losses or deductions. Sale gains use a proportional cost estimate; actual pooling, transaction costs, losses and settlement aren’t modelled.</p><p>The future comparison assumes a 20% gain, today’s rates and no remaining future annual exemption. ${s.isa?'Eligible ISA gains are sheltered. ':''}Income, fees, future law changes and tax on later company withdrawals are excluded. Company tax is before any personal extraction tax. This is not a complete optimisation or a suitability assessment. EIS relief is conditional and excluded from the tax total.</p><p><a href="https://www.gov.uk/capital-gains-tax/rates" target="_blank" rel="noopener">HMRC CGT rates ↗</a> · <a href="https://www.gov.uk/corporation-tax-rates/rates" target="_blank" rel="noopener">Corporation Tax ↗</a> · <a href="https://www.gov.uk/guidance/venture-capital-schemes-tax-relief-for-investors" target="_blank" rel="noopener">EIS conditions ↗</a></p></details></div>`}
function bindWizard(){if(!view().startsWith('invest/'))return;sessionStorage.setItem(('ron-investment-draft-'+(window.RON_REGION||'uk')),JSON.stringify(plan));const step=view().split('/')[1];document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(step==='type'){plan.type=b.dataset.choice;plan.route='auto';navigate('invest/'+steps()[1])}else if(step==='eis'){plan.eis=b.dataset.choice;navigate('invest/amount')}else if(step==='goal'){plan.goal=b.dataset.choice;navigate('invest/amount')}else{plan.years=b.dataset.choice;plan.disposal='';navigate('invest/funding')}});if($('#flow-amount'))$('#flow-amount').onsubmit=e=>{e.preventDefault();plan.amount=Number($('#flow-sum').value);plan.name=$('#flow-name')?.value.trim()||'';if($('#flow-name')&&!plan.name)return;navigate('invest/horizon')};if($('#flow-date'))$('#flow-date').onsubmit=e=>{e.preventDefault();const date=$('#flow-disposal').value;if(!date){$('#flow-disposal').required=true;$('#flow-disposal').reportValidity();return}plan.disposal=date;plan.years=String(Math.max(1,Math.round((new Date(date)-new Date(today))/31557600000)));navigate('invest/funding')};for(const k of ['cross','sales'])if($('#flow-'+k))$('#flow-'+k).onchange=e=>{plan[k]=e.target.checked;plan.route='auto';render()};document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{plan.route=b.dataset.route;render()});if($('#flow-to-review'))$('#flow-to-review').onclick=()=>navigate('invest/review');if($('#flow-save'))$('#flow-save').onclick=()=>{const scenario=chooseScenario(compareRoutes(plan),plan);if(scenario.shortfall>.01)return;state.requests.push({...structuredClone(plan),name:plan.name||(plan.type==='fund'?'Fund portfolio':'Investment shortlist'),scenario,id:crypto.randomUUID(),status:'Awaiting Partner review',created:new Date().toISOString()});if(plan.disposal)state.journey.push({id:crypto.randomUUID(),date:plan.disposal,kind:'trade',name:'Planned disposal: '+(plan.name||'fund portfolio'),owner:scenario.route==='personal'?'Personal':'Company',amount:0,status:'Planning placeholder · value to assess',note:'Future proceeds and tax are unconfirmed. The request includes a hypothetical 20% gain scenario, not a forecast.'});persist();navigate('review');note('Plan saved in this browser. Your Partner has not been notified.')}}
// Keep other app entry points on pages, including Upload and report previews.
upload=function(){navigate('files')};
const originalTaxExperience=taxPage;taxPage=function(){return originalTaxExperience().replace('Tax. In plain English.','Tax').replace('Your personal and company position. UK illustrative figures.','What’s due. What’s left. What to plan for.')};
const originalMoneyExperience=moneyPage;moneyPage=function(){return originalMoneyExperience().replace('Your money.','Your money')};
$('#simple-dialog').addEventListener('cancel',e=>e.preventDefault());render();
